mapper.select:
SELECT id, category, item_id AS itemId, neighbor_id AS neighborId,
       similarity, updated_at AS updatedAt
FROM recommendation_item_similarity
WHERE category = #{category}
  AND item_id = #{itemId}
  AND neighbor_id != #{itemId}
ORDER BY similarity DESC
LIMIT #{limit}

SELECT id, category, item_id AS itemId, neighbor_id AS neighborId, similarity, updated_at AS updatedAt FROM recommendation_item_similarity WHERE category = #{category} AND item_id IN
#{id}
ORDER BY item_id, similarity DESC
